"""Retrieve historical experiment data for Transformer inference."""import pandas as pdfrom sqlalchemy import selectfrom co2_submission.deployment.database import (    Experiment,    ProcessMeasurement,    get_session_factory,)def load_experiment_from_database(experiment_name, origin_row=None):    """    Retrieve an experiment from PostgreSQL.    If origin_row is supplied, retrieve only measurements    available through that forecast origin.    """    Session = get_session_factory()    with Session() as session:        experiment = session.scalar(            select(Experiment).where(                Experiment.name == experiment_name            )        )        if experiment is None:            raise ValueError(                f"Experiment not found: {experiment_name}"            )        query = (            select(ProcessMeasurement)            .where(                ProcessMeasurement.experiment_id == experiment.id            )            .order_by(ProcessMeasurement.row_index)        )        if origin_row is not None:            query = query.where(                ProcessMeasurement.row_index <= origin_row            )        records = session.scalars(query).all()    if not records:        raise ValueError(            f"No measurements found for {experiment_name}"        )    rows = []    for record in records:        row = {            "timestamp": pd.Timestamp(record.timestamp),            **record.measurements,        }        rows.append(row)    frame = pd.DataFrame(rows)    frame["timestamp"] = pd.to_datetime(frame["timestamp"])    return frame.reset_index(drop=True)